            const wchar_t* steps[]={L"Arte e recursos do programa",L"Preferências e calibração",L"Leitor em segundo plano"};
            for(unsigned i=0;i<3;++i){SolidBrush dot(startupStage>i?pink:muted);g.FillEllipse(&dot,x+34,y+115+i*28,6.f,6.f);text(g,steps[i],{x+52,y+108+i*28,422,24},13,startupStage>i?white:muted);}
            text(g,startupStage==3?L"Pronto. Abrindo o painel…":L"Preparando o programa…",{x+32,y+207,456,25},13,muted);
            for(unsigned i=0;i<3;++i)card(g,{x+32+i*155,y+252,146,4},startupStage>i?pink:Color(255,64,49,78),2);
