        text(g,tab==0?L"RAGE / ACOMPANHAMENTO":tab==1?L"SISTEMA / SESSÃO":L"SENSIBILIDADE / CALIBRAÇÃO",{746,240,292,28},15,white,true);
        if(tab==0){toggle(g,20,287,L"Rage contínuo",s.rage);toggle(g,22,333,L"Alvos sem equipe*",s.unknownTargets);button(g,23,{746,386,292,35},s.bone==Head?L"Região / Cabeça":s.bone==Neck?L"Região / Pescoço":s.bone==Chest?L"Região / Tronco":L"Região / Pelve");button(g,24,{746,434,292,35},L"FOV / "+std::to_wstring(int(s.radius))+L" px @1080");button(g,26,{746,482,292,35},s.key==2?L"Ativação / Mouse 2":s.key==VK_SHIFT?L"Ativação / Shift":L"Ativação / Mouse 4");text(g,L"*Sem filtro confirmado de equipe, vida\nou jogador local. Experimental.",{746,538,292,48},12,muted);}
        else if(tab==1){text(g,wide(f->status),{746,290,292,45},17,white,true);text(g,wide(f->error),{746,344,292,75},12,muted);button(g,28,{746,434,292,35},L"Salvar preferências");button(g,29,{746,482,292,35},L"Exportar diagnóstico");button(g,30,{746,530,292,35},L"Restaurar ajustes");}
