        float statusX=compact?20.f:40.f,statusY=compact?380.f:450.f,statusW=compact?400.f:640.f;
        card(g,{statusX,statusY,statusW,104},Color(205,17,16,33),10);
        text(g,L"ESTADO DO CONTROLE",{statusX+18,statusY+13,statusW-36,20},10,pink,true);
